/**
 * Store parity for the GH-6193 scalar extension functions: the placement queries of the MemoryStore test
 * ({@code ExtensionFunctionPlacementSparqlTest}) must return identical rows on an {@link LmdbStore} with native
 * evaluation enabled, whose expression compilers decline the extension functions (census {@code GENERIC}) and fall back
 * to generic evaluation. The NativeStore is not on this module's test classpath, so parity is MemoryStore vs LMDB.
 */
public class LmdbExtensionFunctionParitySparqlTest {

	private static final String PREFIXES = "PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n"
			+ "PREFIX mathf: <http://rdf4j.org/function/math#>\n"
			+ "PREFIX strf: <http://rdf4j.org/function/string#>\n"
			+ "PREFIX dtf: <http://rdf4j.org/function/datetime#>\n"
			+ "PREFIX agg: <http://rdf4j.org/aggregate#>\n"
			+ "PREFIX winf: <http://rdf4j.org/function/window#>\n"
			+ "PREFIX textf: <http://rdf4j.org/function/text#>\n"
			+ "PREFIX jsonf: <http://rdf4j.org/function/json#>\n"
			+ "PREFIX arrf: <http://rdf4j.org/function/array#>\n"
			+ "PREFIX bitf: <http://rdf4j.org/function/bitwise#>\n"
			+ "PREFIX encf: <http://rdf4j.org/function/encoding#>\n"
			+ "PREFIX miscf: <http://rdf4j.org/function/misc#>\n"
			+ "PREFIX ex: <http://example.org/>\n";

	private static final String DATA = "@prefix ex: <http://example.org/> .\n"
			+ "@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .\n"
			+ "@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .\n"
			+ "ex:a ex:n 3 ; ex:s \"alpha,beta\" ; ex:d \"2024-03-05T10:00:00Z\"^^xsd:dateTime ;"
			+ " ex:doc \"{\\\"k\\\":2,\\\"t\\\":\\\"x\\\"}\"^^rdf:JSON .\n"
			+ "ex:b ex:n 10 ; ex:s \"gamma\" ; ex:d \"2023-12-31T23:59:59Z\"^^xsd:dateTime ;"
			+ " ex:doc \"{\\\"k\\\":7,\\\"t\\\":\\\"y\\\"}\"^^rdf:JSON .\n"
			+ "ex:c ex:n 3 ; ex:s \"alpha,beta\" ; ex:d \"2024-03-05T10:00:00Z\"^^xsd:dateTime ;"
			+ " ex:doc \"{\\\"k\\\":2,\\\"t\\\":\\\"x\\\"}\"^^rdf:JSON .\n"
			+ "ex:d ex:n 6 ; ex:s \"delta,eps,zeta\" ; ex:d \"2024-07-01T00:00:00Z\"^^xsd:dateTime ;"
			+ " ex:doc \"{\\\"k\\\":1,\\\"t\\\":\\\"z\\\"}\"^^rdf:JSON .\n";

	private static final String PATTERN = "?x ex:n ?n ; ex:s ?s ; ex:d ?d ; ex:doc ?doc .";

	static Stream<Arguments> families() {
		return Stream.of(
				Arguments.of("mathf", "mathf:pow(?n, 2)", "mathf:pow(?m, 2)"),
				Arguments.of("strf", "strf:reverse(?s)", "strf:reverse(?m)"),
				Arguments.of("dtf", "dtf:dayOfYear(?d)", "dtf:dayOfYear(?m)"),
				Arguments.of("textf", "textf:levenshtein(?s, \"alpha\")", "textf:levenshtein(?m, \"alpha\")"),
				Arguments.of("jsonf", "jsonf:jsonValue(?doc, \"$.k\")", "jsonf:jsonValue(?m, \"$.k\")"),
				Arguments.of("arrf", "arrf:arrayLength(strf:split(?s, \",\"))", "arrf:arrayLength(?m)"),
				Arguments.of("bitf", "bitf:bitAnd(?n, 6)", "bitf:bitAnd(?m, 6)"),
				Arguments.of("encf", "encf:toHex(?s)", "encf:toHex(?m)"),
				Arguments.of("miscf", "miscf:nullIf(?n, 10)", "miscf:nullIf(?m, 10)"));
	}

	@TempDir
	static File dataDir;

	private static SailRepository lmdb;
	private static SailRepository memory;

	@BeforeAll
	static void setUp() throws Exception {
		lmdb = new SailRepository(
				new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true)));
		memory = new SailRepository(new MemoryStore());
		for (SailRepository repository : List.of(lmdb, memory)) {
			try (RepositoryConnection conn = repository.getConnection()) {
				conn.add(new StringReader(DATA), "", RDFFormat.TURTLE);
			}
		}
	}

	@AfterAll
	static void tearDown() {
		lmdb.shutDown();
		memory.shutDown();
	}

	@ParameterizedTest(name = "{0}: {1}")
	@MethodSource("families")
	void placementQueriesGiveIdenticalRowsOnLmdbAndMemoryStore(String family, String expression, String unbound) {
		List<String> queries = new ArrayList<>();
		queries.add("SELECT ?x (" + expression + " AS ?r) WHERE { " + PATTERN + " } ORDER BY ?x");
		queries.add("SELECT ?x ?r WHERE { " + PATTERN + " BIND(" + expression + " AS ?r) } ORDER BY ?x");
		queries.add("SELECT ?x ?r WHERE { { SELECT ?x (" + expression + " AS ?r) WHERE { " + PATTERN + " } } }"
				+ " ORDER BY ?x");
		queries.add("SELECT ?x WHERE { " + PATTERN + " } ORDER BY (" + expression + ") ?x");
		queries.add("SELECT ?k (COUNT(?x) AS ?c) WHERE { " + PATTERN + " } GROUP BY (" + expression + " AS ?k)");
		queries.add("SELECT ?x ?n ?r WHERE { " + PATTERN + " OPTIONAL { ?x ex:missing ?m } BIND(" + unbound
				+ " AS ?r) } ORDER BY ?x");
		queries.add("SELECT ?x WHERE { " + PATTERN + " OPTIONAL { ?x ex:missing ?m } FILTER(" + unbound + " = 1) }");
		// FILTER against each value the MemoryStore computes for the expression
		List<String> memoryValues = new ArrayList<>();
		for (BindingSet row : query(memory, queries.get(0))) {
			if (row.hasBinding("r")) {
				memoryValues.add(NTriplesUtil.toNTriplesString(row.getValue("r")));
			}
		}
		assertThat(memoryValues).as(family + " evaluates on at least one row").isNotEmpty();
		for (String value : memoryValues) {
			queries.add("SELECT ?x WHERE { " + PATTERN + " FILTER(" + expression + " = " + value + ") } ORDER BY ?x");
		}
		for (String query : queries) {
			List<String> onMemory = normalise(query(memory, query), query.contains("GROUP BY"));
			List<String> onLmdb = normalise(query(lmdb, query), query.contains("GROUP BY"));
			assertThat(onLmdb).as(family + "\n" + query).containsExactlyElementsOf(onMemory);
		}
		assertThat(query(lmdb, queries.get(0))).as(family + " SELECT expression rows").hasSize(4);
	}

	@Test
	void everyFunctionTypeInOneSelectGivesIdenticalRowsOnLmdbAndMemoryStore() {
		String query = "SELECT * WHERE {"
				+ " { SELECT ?x ?n ?s ?d ?doc (winf:rowNumber(winf:orderBy(?x)) AS ?rn) WHERE { " + PATTERN + " } }"
				+ " { SELECT (agg:median(?n2) AS ?med) (agg:countIf(?n2 > 5) AS ?big) WHERE { ?y ex:n ?n2 } }"
				+ " (?s \",\") strf:split (?tag)"
				+ " BIND(mathf:pow(?n, 2) AS ?p) BIND(strf:reverse(?tag) AS ?rev) BIND(dtf:dayOfYear(?d) AS ?doy)"
				+ " BIND(textf:levenshtein(?tag, \"alpha\") AS ?lev) BIND(jsonf:jsonValue(?doc, \"$.k\") AS ?jv)"
				+ " BIND(arrf:arrayLength(strf:split(?s, \",\")) AS ?len) BIND(bitf:bitAnd(?n, 6) AS ?band)"
				+ " BIND(encf:toHex(?tag) AS ?hex) BIND(miscf:nullIf(?n, 10) AS ?nn)"
				+ " } ORDER BY ?x ?tag";
		List<String> onMemory = normalise(query(memory, query), false);
		List<String> onLmdb = normalise(query(lmdb, query), false);
		assertThat(onMemory).hasSize(8);
		assertThat(onLmdb).containsExactlyElementsOf(onMemory);
	}

	private static List<BindingSet> query(SailRepository repository, String query) {
		try (RepositoryConnection conn = repository.getConnection();
				TupleQueryResult result = conn.prepareTupleQuery(PREFIXES + query).evaluate()) {
			return new ArrayList<>(QueryResults.asList(result));
		}
	}

	/** Rows as canonical N-Triples strings; unordered (GROUP BY) results are sorted before comparison. */
	private static List<String> normalise(List<BindingSet> rows, boolean sort) {
		List<String> lines = new ArrayList<>();
		for (BindingSet row : rows) {
			TreeMap<String, String> bindings = new TreeMap<>();
			for (String name : row.getBindingNames()) {
				if (row.hasBinding(name)) {
					bindings.put(name, NTriplesUtil.toNTriplesString(row.getValue(name)));
				}
			}
			lines.add(bindings.toString());
		}
		if (sort) {
			lines.sort(null);
		}
		return lines;
	}
}
